// R2 — Validate Input (proposal-regenerate)
// UUID task_id + non-empty profile_id + non-empty original_proposal.
// Throws on failure → n8n 500 (dashboard pre-validates; this is defense-in-depth).
const body = items[0].json.body ?? items[0].json;
const taskId = body.task_id;
const profileId = body.profile_id;
const originalProposal = body.original_proposal;
const feedbackCategories = Array.isArray(body.feedback_categories) ? body.feedback_categories : [];
const feedbackNote = (body.feedback_note === null || body.feedback_note === undefined) ? null : String(body.feedback_note);
const requestedBy = body.requested_by ?? null;
const requestId = body.request_id ?? null;

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!taskId || typeof taskId !== "string" || !UUID_RE.test(taskId)) {
  throw new Error(`Invalid task_id: ${taskId}`);
}
if (!profileId || typeof profileId !== "string") {
  throw new Error("Missing profile_id");
}
if (!originalProposal || typeof originalProposal !== "string" || originalProposal.trim().length === 0) {
  throw new Error("Missing original_proposal");
}

return [{ json: {
  task_id: taskId.toLowerCase(),
  profile_id: profileId,
  original_proposal: originalProposal,
  feedback_categories: feedbackCategories,
  feedback_note: feedbackNote,
  requested_by: requestedBy,
  request_id: requestId,
} }];

// R5 — Build Proposal Writer Input (proposal-regenerate)
// Replicates the parent workflow's `Build GPT Input` node EXACTLY (profile section,
// job title/description/budget/skills/client context), then appends a feedback block.
//
// Sources:
//   - validated input  : $('R2 - Validate Input').first().json  (task_id, profile_id, original_proposal, feedback_categories, feedback_note)
//   - job payload       : $('R3 - Load Job Payload').first().json  (flat shape from /api/tasks/:id/job-payload)
//   - profile mapping   : $('R4 - Load Profile Mapping').first().json  (map keyed by profile_name; each entry has .profile_id/.upwork/.stack/.assigned_agent)

const v = $('R2 - Validate Input').first().json;
const payload = $('R3 - Load Job Payload').first().json;
const mapping = $('R4 - Load Profile Mapping').first().json || {};

// ── Resolve profile entry by profile_id (mapping is keyed by profile_name) ──
let profileEntry = null;
let profileName = v.profile_id;
for (const key of Object.keys(mapping)) {
  const e = mapping[key];
  if (e && e.profile_id === v.profile_id) { profileEntry = e; profileName = key; break; }
}
// Fallback: maybe the incoming id IS the profile_name key
if (!profileEntry && mapping[v.profile_id]) { profileEntry = mapping[v.profile_id]; profileName = v.profile_id; }

const upwork = profileEntry && profileEntry.upwork ? profileEntry.upwork : null;
const stack = profileEntry && profileEntry.stack ? profileEntry.stack : '';
const assignedAgent = profileEntry && profileEntry.assigned_agent ? profileEntry.assigned_agent : (payload._assigned_agent || '');

// ── Project the flat job-payload into the parent's `job.*` shape ──
let budgetStr = '';
if (payload.budget_type === 'fixed' && payload.fixed_amount != null) {
  budgetStr = '$' + payload.fixed_amount + ' fixed';
} else if (payload.budget_type === 'hourly') {
  if (payload.budget_min != null && payload.budget_max != null) budgetStr = '$' + payload.budget_min + '-$' + payload.budget_max + '/hr';
  else if (payload.budget_min != null) budgetStr = '$' + payload.budget_min + '/hr';
}
const job = {
  title: payload.title || '',
  description: String(payload.description || ''),
  budget: budgetStr,
  skills: Array.isArray(payload.skills_required) ? payload.skills_required : [],
  clientCountry: (payload.client && payload.client.country) || '',
  clientRating: (payload.client && payload.client.rating != null) ? payload.client.rating : '',
  clientSpent: (payload.client && payload.client.total_spent != null) ? payload.client.total_spent : '',
  clientHires: (payload.client && payload.client.hires != null) ? payload.client.hires : '',
};

// Budget display
const budgetRaw = String(job.budget || '');
const budgetDisplay = budgetRaw || 'Not specified';

// Skills display
const skillsDisplay = Array.isArray(job.skills) ? job.skills.join(', ') : String(job.skills || 'N/A');

// Hook rotation per profile (A → B → A → B...)
const staticData = $getWorkflowStaticData('global');
if (!staticData.hookRotation) staticData.hookRotation = {};
const profileKey = v.profile_id || 'default';
const lastHook = staticData.hookRotation[profileKey] || 'B';
const useHook = lastHook === 'A' ? 'B' : 'A';
staticData.hookRotation[profileKey] = useHook;

// Build profile section
const profileLines = [];
profileLines.push(`=== FREELANCER PROFILE ===`);
profileLines.push(`Name: ${upwork && upwork.name ? upwork.name : profileName}`);
profileLines.push(`Profile ID: ${profileName}`);
profileLines.push(`Agent: ${assignedAgent}`);

if (upwork) {
  if (upwork.title) profileLines.push(`Title: ${upwork.title}`);
  const meta = [];
  if (upwork.top_rated_status) meta.push(upwork.top_rated_status.replace(/_/g, ' '));
  if (upwork.hourly_rate) meta.push(`$${upwork.hourly_rate}/hr`);
  if (upwork.rating && upwork.rating > 0) meta.push(`${upwork.rating}/5 client rating`);
  if (upwork.total_jobs) meta.push(`${upwork.total_jobs} jobs completed`);
  if (upwork.total_hours) meta.push(`${upwork.total_hours}h logged`);
  if (upwork.last_worked_on) meta.push(`last worked ${upwork.last_worked_on}`);
  if (meta.length > 0) profileLines.push(`Track Record: ${meta.join(' · ')}`);
  if (upwork.skills_summary) profileLines.push(`Skills: ${upwork.skills_summary}`);
  if (stack) profileLines.push(`Stack Focus: ${stack}`);

  if (upwork.bio) {
    profileLines.push('');
    profileLines.push('Bio / Overview:');
    profileLines.push(String(upwork.bio).substring(0, 1000));
  }

  if (Array.isArray(upwork.portfolio) && upwork.portfolio.length > 0) {
    profileLines.push('');
    profileLines.push('Portfolio Highlights:');
    for (const p of upwork.portfolio.slice(0, 3)) {
      const t = p.title || '(untitled)';
      const d = String(p.description || '').substring(0, 220);
      profileLines.push(d ? `- ${t}: ${d}` : `- ${t}`);
    }
  }
} else {
  if (stack) profileLines.push(`Stack Focus: ${stack}`);
  profileLines.push('(No Upwork snapshot available for this profile — proceed with stack/agent info only.)');
}

profileLines.push('');
profileLines.push(`USE HOOK: ${useHook}`);
profileLines.push('');
profileLines.push('PROFILE-SPECIFIC INSTRUCTIONS:');
profileLines.push((profileEntry && profileEntry.custom_gpt_instructions) || 'No additional instructions.');

// ── Feedback block (the regenerate-specific addition) ──
const cats = Array.isArray(v.feedback_categories) ? v.feedback_categories.join(', ') : '';
const note = (v.feedback_note && String(v.feedback_note).trim().length > 0) ? String(v.feedback_note) : 'none';

const gptInput = [
  ...profileLines,
  '',
  '=== JOB TITLE ===',
  job.title,
  '',
  '=== JOB DESCRIPTION ===',
  job.description.substring(0, 2000),
  '',
  '=== BUDGET ===',
  budgetDisplay,
  '',
  '=== REQUIRED SKILLS ===',
  skillsDisplay,
  '',
  '=== CLIENT CONTEXT ===',
  `- Location: ${job.clientCountry || 'Not specified'}`,
  `- Rating: ${job.clientRating || 'N/A'}/5`,
  `- Total Spent: $${job.clientSpent || '0'}`,
  `- Total Hires: ${job.clientHires || '0'}`,
  '',
  '=== PREVIOUS PROPOSAL (rewrite/improve this) ===',
  v.original_proposal,
  '',
  '=== AGENT FEEDBACK — the previous proposal was rejected for these reasons, fix them ===',
  `Problems: ${cats}`,
  `Notes: ${note}`,
  '',
  'Rewrite the proposal addressing every problem above. Keep all the structure/format rules.',
  'Write the improved proposal now.'
  // Strip lone UTF-16 surrogates left by substring() cuts inside emoji pairs (Anthropic HTTP 400 guard).
].join('\n').replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, '');

return [{ json: { task_id: v.task_id, profile_id: v.profile_id, profile_name: profileName, gptInput } }];
